const express = require('express');
const app = express();

// Middleware to parse JSON request bodies
app.use(express.json());

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// POST endpoint with input validation
app.post('/users', (req, res) => {
  // Check if name field exists and is a string
  if (!req.body.name) {
    return res.status(400).json({
      error: 'Missing required field: name',
      message: 'The name field is required'
    });
  }

  if (typeof req.body.name !== 'string') {
    return res.status(400).json({
      error: 'Invalid field type',
      message: 'The name field must be a string'
    });
  }

  // If validation passes, process the request
  // For now, just return success with the provided name
  const newUser = {
    id: Date.now(), // Simple ID generation
    name: req.body.name,
    email: req.body.email || `${req.body.name.toLowerCase()}@example.com`
  };

  res.status(201).json({
    message: 'User created successfully',
    user: newUser
  });
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

