{
  "name": "express-validation-app",
  "version": "1.0.0",
  "description": "Express application with input validation",
  "main": "app.js",
  "scripts": {
    "start": "node app.js",
    "dev": "nodemon app.js",
    "test": "echo \"No tests specified\" && exit 0"
  },
  "keywords": ["express", "validation", "api"],
  "author": "",
  "license": "ISC",
  "dependencies": {
    "express": "^4.18.2"
  },
  "devDependencies": {
    "nodemon": "^3.0.1"
  },
  "engines": {
    "node": ">=14.0.0",
    "npm": ">=6.0.0"
  }
}

const http = require('http');

const baseUrl = 'http://localhost:3000';
const testData = [
  {
    name: 'Valid request with string name',
    data: { name: 'Alice' },
    expectedStatus: 201,
    description: 'Should accept valid string name'
  },
  {
    name: 'Missing name field',
    data: {},
    expectedStatus: 400,
    description: 'Should reject missing name field'
  },
  {
    name: 'Null name field',
    data: { name: null },
    expectedStatus: 400,
    description: 'Should reject null name field'
  },
  {
    name: 'Number name field',
    data: { name: 123 },
    expectedStatus: 400,
    description: 'Should reject number as name'
  },
  {
    name: 'Boolean name field',
    data: { name: true },
    expectedStatus: 400,
    description: 'Should reject boolean as name'
  },
  {
    name: 'Array name field',
    data: { name: ['Alice'] },
    expectedStatus: 400,
    description: 'Should reject array as name'
  },
  {
    name: 'Object name field',
    data: { name: { first: 'Alice' } },
    expectedStatus: 400,
    description: 'Should reject object as name'
  },
  {
    name: 'Empty string name',
    data: { name: '' },
    expectedStatus: 201,
    description: 'Should accept empty string (still a string)'
  }
];

function makeRequest(testCase) {
  return new Promise((resolve, reject) => {
    const data = JSON.stringify(testCase.data);

    const options = {
      hostname: 'localhost',
      port: 3000,
      path: '/users',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(data)
      }
    };

    const req = http.request(options, (res) => {
      let responseData = '';

      res.on('data', (chunk) => {
        responseData += chunk;
      });

      res.on('end', () => {
        const passed = res.statusCode === testCase.expectedStatus;
        resolve({
          testName: testCase.name,
          statusCode: res.statusCode,
          expectedStatus: testCase.expectedStatus,
          passed: passed,
          response: responseData ? JSON.parse(responseData) : null,
          description: testCase.description
        });
      });
    });

    req.on('error', (error) => {
      reject({
        testName: testCase.name,
        error: error.message,
        description: testCase.description
      });
    });

    req.write(data);
    req.end();
  });
}

async function runTests() {
  console.log('🚀 Running validation tests...\n');

  const results = [];

  for (const testCase of testData) {
    try {
      const result = await makeRequest(testCase);
      results.push(result);
    } catch (error) {
      results.push({
        testName: error.testName,
        error: error.error,
        passed: false,
        description: error.description
      });
    }
  }

  // Print results
  let passedCount = 0;
  results.forEach((result, index) => {
    console.log(`Test ${index + 1}: ${result.testName}`);
    console.log(`  ${result.description}`);

    if (result.error) {
      console.log(`  ❌ Error: ${result.error}`);
    } else if (result.passed) {
      console.log(`  ✅ PASSED - Status ${result.statusCode} (expected ${result.expectedStatus})`);
      passedCount++;
    } else {
      console.log(`  ❌ FAILED - Status ${result.statusCode} (expected ${result.expectedStatus})`);
      if (result.response) {
        console.log(`     Response: ${JSON.stringify(result.response)}`);
      }
    }
    console.log();
  });

  console.log(`\n📊 Summary: ${passedCount}/${results.length} tests passed`);

  if (passedCount === results.length) {
    console.log('🎉 All validation tests passed! Ready for deployment.');
  } else {
    console.log('❌ Some tests failed. Check validation logic.');
    process.exit(1);
  }
}

// First, check if server is running
function checkServer() {
  return new Promise((resolve) => {
    const req = http.request({
      hostname: 'localhost',
      port: 3000,
      path: '/health',
      method: 'GET',
      timeout: 2000
    }, (res) => {
      resolve(true);
    });

    req.on('error', () => {
      resolve(false);
    });

    req.on('timeout', () => {
      req.destroy();
      resolve(false);
    });

    req.end();
  });
}

async function main() {
  console.log('🔍 Checking if server is running on port 3000...');
  const serverRunning = await checkServer();

  if (!serverRunning) {
    console.log('❌ Server is not running. Please start the server with:');
    console.log('   node app.js');
    console.log('\nThen run:');
    console.log('   node test_validation.js');
    process.exit(1);
  }

  await runTests();
}

if (require.main === module) {
  main();
}

module.exports = { runTests };

