// User API Application
// Production-ready Express.js API with input validation

const express = require('express');
const app = express();

// Get port from environment variable or default to 3000
const PORT = process.env.PORT || 3000;

// Add JSON body parsing middleware with size limit
app.use(express.json({ limit: '1mb' }));

// Request logging middleware for production
app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    const duration = Date.now() - start;
    console.log(`${new Date().toISOString()} ${req.method} ${req.url} ${res.statusCode} ${duration}ms`);
  });
  next();
});

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});

// Get all users
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Create new user with input validation
app.post('/users', (req, res) => {
  try {
    const { name } = req.body;

    // Validation: Check if name is missing or not a string
    if (name === undefined || name === null) {
      return res.status(400).json({ 
        error: 'Missing required field: name',
        code: 'VALIDATION_ERROR'
      });
    }

    if (typeof name !== 'string') {
      return res.status(400).json({ 
        error: 'Field "name" must be a string',
        code: 'TYPE_ERROR'
      });
    }

    // Additional validation: Check if name is empty or only whitespace
    const trimmedName = name.trim();
    if (trimmedName === '') {
      return res.status(400).json({ 
        error: 'Field "name" cannot be empty or whitespace only',
        code: 'EMPTY_VALUE_ERROR'
      });
    }

    // If validation passes, create a new user
    const newUser = {
      id: Date.now(), // Simple ID generation
      name: trimmedName,
      email: `${trimmedName.toLowerCase().replace(/\s+/g, '.')}@example.com`,
      createdAt: new Date().toISOString()
    };

    res.status(201).json({
      message: 'User created successfully',
      user: newUser
    });

  } catch (error) {
    console.error('Error creating user:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      code: 'INTERNAL_ERROR'
    });
  }
});

// 404 handler for undefined routes
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Route not found',
    code: 'NOT_FOUND'
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);
  res.status(500).json({ 
    error: 'Internal server error',
    code: 'INTERNAL_ERROR'
  });
});

// Start server
const server = app.listen(PORT, () => {
  console.log(`Server running in ${process.env.NODE_ENV || 'development'} mode on port ${PORT}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received. Shutting down gracefully...');
  server.close(() => {
    console.log('Server closed.');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received. Shutting down gracefully...');
  server.close(() => {
    console.log('Server closed.');
    process.exit(0);
  });
});

module.exports = app;

