#!/usr/bin/env node

const http = require('http');

const testCases = [
  {
    name: 'Missing name field',
    data: { age: 25 },
    expectedStatus: 400,
    expectedError: 'Missing required field: name'
  },
  {
    name: 'Name is null',
    data: { name: null },
    expectedStatus: 400,
    expectedError: 'Missing required field: name'
  },
  {
    name: 'Name is number',
    data: { name: 123 },
    expectedStatus: 400,
    expectedError: 'Field "name" must be a string'
  },
  {
    name: 'Name is object',
    data: { name: { first: 'John', last: 'Doe' } },
    expectedStatus: 400,
    expectedError: 'Field "name" must be a string'
  },
  {
    name: 'Name is array',
    data: { name: ['John', 'Doe'] },
    expectedStatus: 400,
    expectedError: 'Field "name" must be a string'
  },
  {
    name: 'Name is boolean',
    data: { name: true },
    expectedStatus: 400,
    expectedError: 'Field "name" must be a string'
  },
  {
    name: 'Empty string name',
    data: { name: '' },
    expectedStatus: 400,
    expectedError: 'Field "name" cannot be empty'
  },
  {
    name: 'Whitespace-only name',
    data: { name: '   ' },
    expectedStatus: 400,
    expectedError: 'Field "name" cannot be empty'
  },
  {
    name: 'Valid string name',
    data: { name: 'John Doe' },
    expectedStatus: 201,
    expectedError: null
  },
  {
    name: 'Valid name with extra fields',
    data: { name: 'Jane Smith', age: 30, email: 'jane@example.com' },
    expectedStatus: 201,
    expectedError: null
  }
];

const serverAddress = 'http://localhost:3000';

console.log('Testing POST /users validation...\n');

async function runTests() {
  for (const testCase of testCases) {
    try {
      const data = JSON.stringify(testCase.data);

      const options = {
        hostname: 'localhost',
        port: 3000,
        path: '/users',
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Content-Length': Buffer.byteLength(data)
        }
      };

      const promise = new Promise((resolve, reject) => {
        const req = http.request(options, (res) => {
          let responseData = '';

          res.on('data', (chunk) => {
            responseData += chunk;
          });

          res.on('end', () => {
            try {
              const parsed = responseData ? JSON.parse(responseData) : {};
              resolve({
                status: res.statusCode,
                body: parsed
              });
            } catch (error) {
              reject(error);
            }
          });
        });

        req.on('error', reject);
        req.write(data);
        req.end();
      });

      const result = await promise;
      const passed = result.status === testCase.expectedStatus &&
        (testCase.expectedError === null || 
         (result.body.message && result.body.message.includes(testCase.expectedError)));

      console.log(`Test: ${testCase.name}`);
      console.log(`  Status: ${result.status} (expected: ${testCase.expectedStatus})`);
      console.log(`  Response: ${JSON.stringify(result.body)}`);
      console.log(`  Result: ${passed ? '✓ PASS' : '✗ FAIL'}`);
      console.log('');

    } catch (error) {
      console.log(`Test: ${testCase.name}`);
      console.log(`  Error: ${error.message}`);
      console.log(`  Result: ✗ FAIL`);
      console.log('');
    }
  }
}

// Check if server is running
const healthCheckOptions = {
  hostname: 'localhost',
  port: 3000,
  path: '/health',
  method: 'GET',
  timeout: 5000
};

http.request(healthCheckOptions, (res) => {
  runTests();
}).on('error', (error) => {
  console.log('Server is not running. Please start the server with: node app.js');
  console.log('Then run: node test_validation.js');
}).end();

