// Test script to verify validation logic
const express = require('express');

// Simulate the validation logic
function validateName(name) {
  if (name === undefined || name === null) {
    return { isValid: false, error: 'Missing required field: name' };
  }

  if (typeof name !== 'string') {
    return { isValid: false, error: 'Invalid field type: name must be a string' };
  }

  if (name.trim() === '') {
    return { isValid: false, error: 'Invalid value: name cannot be empty or whitespace only' };
  }

  return { isValid: true, name: name.trim() };
}

// Test cases
const testCases = [
  { input: undefined, expected: 'Missing required field: name' },
  { input: null, expected: 'Missing required field: name' },
  { input: 123, expected: 'Invalid field type: name must be a string' },
  { input: {}, expected: 'Invalid field type: name must be a string' },
  { input: [], expected: 'Invalid field type: name must be a string' },
  { input: '', expected: 'Invalid value: name cannot be empty or whitespace only' },
  { input: '   ', expected: 'Invalid value: name cannot be empty or whitespace only' },
  { input: 'John', expected: 'Valid' },
  { input: '  Jane Doe  ', expected: 'Valid' },
];

console.log('Testing validation logic...\n');
let passed = 0;
let failed = 0;

testCases.forEach((testCase, index) => {
  const result = validateName(testCase.input);

  if (testCase.expected === 'Valid') {
    if (result.isValid) {
      console.log(`✓ Test ${index + 1} PASSED: "${testCase.input}" -> Valid`);
      passed++;
    } else {
      console.log(`✗ Test ${index + 1} FAILED: "${testCase.input}" -> Expected Valid, got "${result.error}"`);
      failed++;
    }
  } else {
    if (!result.isValid && result.error === testCase.expected) {
      console.log(`✓ Test ${index + 1} PASSED: "${testCase.input}" -> "${result.error}"`);
      passed++;
    } else {
      console.log(`✗ Test ${index + 1} FAILED: "${testCase.input}" -> Expected "${testCase.expected}", got "${result.isValid ? 'Valid' : result.error}"`);
      failed++;
    }
  }
});

console.log(`\nTest Results: ${passed} passed, ${failed} failed`);
process.exit(failed > 0 ? 1 : 0);

