const request = require('supertest');
const app = require('../app');

describe('User Management API', () => {
  describe('GET /health', () => {
    it('should return health status', async () => {
      const res = await request(app).get('/health');
      expect(res.statusCode).toBe(200);
      expect(res.body).toHaveProperty('status', 'ok');
      expect(res.body).toHaveProperty('timestamp');
    });
  });

  describe('GET /users', () => {
    it('should return list of users', async () => {
      const res = await request(app).get('/users');
      expect(res.statusCode).toBe(200);
      expect(Array.isArray(res.body)).toBe(true);
      expect(res.body.length).toBe(2);
    });
  });

  describe('POST /users', () => {
    it('should create a new user with valid name', async () => {
      const res = await request(app)
        .post('/users')
        .send({ name: 'Charlie' });

      expect(res.statusCode).toBe(201);
      expect(res.body).toHaveProperty('message', 'User created successfully');
      expect(res.body.user).toHaveProperty('name', 'Charlie');
      expect(res.body.user).toHaveProperty('id');
      expect(res.body.user).toHaveProperty('created');
    });

    it('should return 400 when name is missing', async () => {
      const res = await request(app)
        .post('/users')
        .send({});

      expect(res.statusCode).toBe(400);
      expect(res.body).toHaveProperty('error', 'Bad Request');
      expect(res.body).toHaveProperty('message', 'Name field is required');
    });

    it('should return 400 when name is not a string', async () => {
      const res = await request(app)
        .post('/users')
        .send({ name: 123 });

      expect(res.statusCode).toBe(400);
      expect(res.body).toHaveProperty('error', 'Bad Request');
      expect(res.body).toHaveProperty('message', 'Name field must be a string');
    });

    it('should return 400 when name is empty string', async () => {
      const res = await request(app)
        .post('/users')
        .send({ name: '' });

      expect(res.statusCode).toBe(400);
      expect(res.body).toHaveProperty('error', 'Bad Request');
      expect(res.body).toHaveProperty('message', 'Name field cannot be empty');
    });

    it('should trim whitespace from name', async () => {
      const res = await request(app)
        .post('/users')
        .send({ name: '  David  ' });

      expect(res.statusCode).toBe(201);
      expect(res.body.user).toHaveProperty('name', 'David');
    });
  });
});

