// Test script to verify the POST endpoint validation
const axios = require('axios');

const BASE_URL = 'http://localhost:3000';

async function testValidation() {
  console.log('Testing POST /user endpoint validation...\n');

  try {
    // Test 1: Missing name field
    console.log('Test 1: Missing name field');
    try {
      const response = await axios.post(`${BASE_URL}/user`, {});
      console.log('Unexpected success:', response.data);
    } catch (error) {
      if (error.response) {
        console.log(`Status: ${error.response.status}`);
        console.log(`Response: ${JSON.stringify(error.response.data, null, 2)}\n`);
      }
    }

    // Test 2: Non-string name field (number)
    console.log('Test 2: Non-string name field (number)');
    try {
      const response = await axios.post(`${BASE_URL}/user`, { name: 123 });
      console.log('Unexpected success:', response.data);
    } catch (error) {
      if (error.response) {
        console.log(`Status: ${error.response.status}`);
        console.log(`Response: ${JSON.stringify(error.response.data, null, 2)}\n`);
      }
    }

    // Test 3: Non-string name field (object)
    console.log('Test 3: Non-string name field (object)');
    try {
      const response = await axios.post(`${BASE_URL}/user`, { name: { first: 'John', last: 'Doe' } });
      console.log('Unexpected success:', response.data);
    } catch (error) {
      if (error.response) {
        console.log(`Status: ${error.response.status}`);
        console.log(`Response: ${JSON.stringify(error.response.data, null, 2)}\n`);
      }
    }

    // Test 4: Empty string name
    console.log('Test 4: Empty string name');
    try {
      const response = await axios.post(`${BASE_URL}/user`, { name: '' });
      console.log('Unexpected success:', response.data);
    } catch (error) {
      if (error.response) {
        console.log(`Status: ${error.response.status}`);
        console.log(`Response: ${JSON.stringify(error.response.data, null, 2)}\n`);
      }
    }

    // Test 5: Whitespace-only name
    console.log('Test 5: Whitespace-only name');
    try {
      const response = await axios.post(`${BASE_URL}/user`, { name: '   ' });
      console.log('Unexpected success:', response.data);
    } catch (error) {
      if (error.response) {
        console.log(`Status: ${error.response.status}`);
        console.log(`Response: ${JSON.stringify(error.response.data, null, 2)}\n`);
      }
    }

    // Test 6: Valid name (should succeed)
    console.log('Test 6: Valid name');
    try {
      const response = await axios.post(`${BASE_URL}/user`, { name: 'John Doe' });
      console.log(`Status: ${response.status}`);
      console.log(`Response: ${JSON.stringify(response.data, null, 2)}\n`);
    } catch (error) {
      console.log('Unexpected error:', error.response?.data || error.message);
    }

    console.log('All tests completed!');
  } catch (error) {
    console.error('Test setup error:', error.message);
  }
}

// Check if server is running first
testValidation();

